window.STUDY_BFA_SHEETS={"intelligence-artificielle":[[{"title":"Définition de l'IA","type":"text","text":"L'intelligence artificielle est un ensemble de techniques permettant aux machines d'imiter certaines capacités humaines : comprendre, communiquer, mémoriser, raisonner, s'adapter et apprendre."},{"title":"Le test de Turing","type":"text","text":"Il évalue si une machine peut produire une conversation difficile à distinguer de celle d'un humain. Ce n'est pas une condition obligatoire pour reconnaître une IA."},{"title":"Formes de l'IA","type":"cards","items":[["Chatbots","communication écrite"],["Voicebots","communication vocale"],["Systèmes de recommandation","Netflix et Spotify"]]},{"title":"Types d'IA","type":"cards","items":[["ANI (Artificial Narrow Intelligence)","IA spécialisée"],["AGI (Artificial General Intelligence)","IA générale, encore un objectif de recherche"]]},{"title":"Intelligence humaine et artificielle","type":"cards","items":[["Humaine","créativité, émotions et expérience"],["Artificielle","rapidité, précision dans certaines tâches et utilisation de données"]]},{"title":"Machine Learning et Deep Learning","type":"cards","items":[["Machine Learning","apprendre à partir de données"],["Régression","prédire une quantité"],["Classification","prédire une catégorie"],["Deep Learning","branche du ML utilisant des réseaux de neurones à plusieurs couches"]]},{"title":"Trois visions de l'IA","type":"cards","items":[["Optimiste","résoudre de nombreux problèmes"],["Pessimiste","dangers potentiels pour l'humanité"],["Réaliste","outil puissant avec des avantages et des limites"]]},{"title":"Risques et économie","type":"cards","items":[["Risques","deepfakes, faux commentaires, désinformation et atteintes à la vie privée"],["Économie","transformation ou suppression de certains emplois, création de nouveaux emplois et productivité"]]},{"title":"L'IA dans les projets","type":"text","text":"Un projet pertinent relie ce que l'IA peut faire à ce qui apporte de la valeur. Vérifier l'utilité et les données, puis tester, évaluer, améliorer et collaborer : c'est un processus itératif."}],[{"title":"Définition du prompt","type":"text","text":"Un prompt est une instruction ou une entrée envoyée à une IA pour obtenir une réponse. Il peut s'agir d'une question, d'un scénario ou d'une instruction complexe."},{"title":"ChatGPT et les LLM","type":"text","text":"ChatGPT utilise un LLM (Large Language Model), un modèle capable de traiter et de générer du langage humain. Le prompt doit être clair, direct et contextualisé."},{"title":"Structure d'un prompt","type":"cards","items":[["Instruction","la tâche"],["Contexte","la situation"],["Input data","les données fournies"],["Output indication","le format de réponse attendu"]]},{"title":"Types de prompts","type":"text","text":"Informatif, question-réponse, génération de contenu et d'idées, explication, étape par étape, analyse, comparaison, prompt par rôle, résumé, synthèse, transformation, reformulation et amélioration."},{"title":"Astuces avancées","type":"text","text":"Utiliser des verbes précis, définir le format et la longueur, préciser ce qu'il faut éviter, donner un exemple, reformuler et utiliser le prompt chaining (enchaînement de prompts)."}]],"comptabilite-gestion":[[{"title":"Définition","type":"text","text":"La comptabilité de gestion est la « cuisine interne » de l’entreprise : elle calcule et analyse les coûts pour aider à prendre des décisions. Elle est généralement facultative, mais très utile."},{"title":"Caractéristiques","type":"text","text":"Elle est flexible, confidentielle et constitue un outil de contrôle de gestion. Son objectif est de maîtriser les coûts grâce à des informations pertinentes."},{"title":"Méthodes de calcul","type":"list","numbered":false,"items":["Coûts complets","imputation rationnelle des charges fixes","Target Costing","ABC","EVA","coûts variables","coûts spécifiques","coût marginal","coûts cachés."]},{"title":"Charges non incorporables","type":"text","text":"Charges de comptabilité générale exclues du calcul des coûts : certaines charges non courantes, charges d’exercices antérieurs, impôt sur le résultat et certaines dotations."},{"title":"Charges calculées","type":"text","text":"Charges dont le montant est recalculé ou réparti pour les besoins de la comptabilité de gestion : charges d’usage, charges étalées et charges abonnées."},{"title":"Charges supplétives","type":"text","text":"Charges ajoutées pour calculer les coûts, sans être enregistrées comme charges en comptabilité générale. Exemple : rémunération théorique des capitaux propres."},{"title":"Formule à retenir","type":"formula","lead":"","formula":"CCG = CG − CNI + CS (formule simplifiée)","text":"CG : charges de comptabilité générale ; CNI : charges non incorporables ; CS : charges supplétives. Ajouter les différences d’incorporation éventuelles."}],[{"title":"Définition d’un coût","type":"text","text":"Un coût est un ensemble de charges associées à un produit, un service ou une activité."},{"title":"Trois critères","type":"cards","items":[["Champ d’application","produit, service ou activité"],["contenu","charges directes/indirectes et fixes/variables"],["moment","coût préétabli (standard) ou constaté (réel)"]]},{"title":"Cycle d’une entreprise commerciale","type":"flow","parts":["Achat","Stockage","Distribution"]},{"title":"Formule du coût d’achat","type":"formula","lead":"","formula":"Coût d’achat = Prix d’achat net + Charges accessoires d’achat + Charges d’approvisionnement","text":""},{"title":"Prix d’achat net","type":"text","text":"Prix d’achat brut diminué des réductions commerciales RRR : rabais, remises et ristournes."},{"title":"Charges accessoires d’achat","type":"text","text":"Dépenses directement liées à l’achat, comme le transport et l’assurance."},{"title":"Charges d’approvisionnement","type":"text","text":"Charges liées aux activités d’achat, de réception et d’approvisionnement de l’entreprise."}]],"entrepreneuriat-business-plan":[[{"title":"Définition","type":"text","text":"L’entrepreneuriat crée de la valeur en transformant une idée en activité économiquement viable. Selon Shane et Venkataraman, il consiste à découvrir, évaluer et exploiter des opportunités de nouveaux biens ou services."},{"title":"L’entrepreneur","type":"text","text":"Il doit être créatif, audacieux et capable de coordonner autrement les facteurs de production."},{"title":"Formes d’innovation","type":"list","numbered":false,"items":["Nouveau produit ou qualité","nouvelle méthode de production","nouveau marché","nouvelles sources d’approvisionnement","nouvelle organisation industrielle."]},{"title":"Avantages","type":"text","text":"Indépendance, autonomie, réalisation d’une passion, revenu élevé potentiel, création d’emplois et innovation."},{"title":"Inconvénients","type":"text","text":"Risques financiers, travail intense, concurrence et pression fiscale."},{"title":"Formes d’entrepreneuriat","type":"cards","items":[["Par nécessité","survie économique"],["D’opportunité","choix"],["Social","problèmes sociaux"],["Technologique","startups"],["Vert","durabilité"],["Féminin","entrepreneuriat porté par des femmes"]]}],[{"title":"Définition","type":"text","text":"Le Business Plan est un dossier d’analyse d’un projet d’investissement expliquant pourquoi, comment et dans quel délai il peut devenir rentable. Il intervient lors d’une création, reprise, lancement ou étude d’abandon."},{"title":"Deux fonctions","type":"text","text":"Document de travail : organiser et gérer le projet. Outil de communication : présenter le projet aux clients, fournisseurs, investisseurs et banques. Validation interne avant diffusion externe."},{"title":"Utilité interne","type":"text","text":"Organiser le travail, fixer les objectifs à court terme, prévoir charges et coûts, contrôler les dépenses, gérer et faire du reporting."},{"title":"Utilité externe","type":"text","text":"Trouver des partenaires financiers, identifier les sources et risques de financement, développer des partenariats commerciaux et industriels."},{"title":"Trois typologies","type":"cards","items":[["Création","nouvelle entreprise"],["Gestion courante","prévisions, cohérence, coordination et communication interne"],["Opérations exceptionnelles","transformation du modèle, fusion-acquisition ou ouverture du capital"]]},{"title":"Business Model vs Business Plan","type":"text","text":"Le Business Model décrit comment l’entreprise fonctionne, crée de la valeur et génère du chiffre d’affaires. Le Business Plan détaille l’organisation, le financement et le développement du projet."}]],"systeme-information-erp":[[{"title":"Système d’information","type":"text","text":"Ensemble de ressources structurées pour acquérir, traiter, mémoriser, transmettre et rendre disponible l’information dans et entre les organisations. L’information soutient la prise de décision."},{"title":"Sources de données","type":"list","numbered":false,"items":["Données internes produites ou détenues par l’entreprise","données externes achetées","données externes publiques."]},{"title":"Définitions fondamentales","type":"cards","items":[["Système","éléments en interaction vers un objectif"],["Base de données","ensemble organisé de données"],["SGBD","Système de Gestion de Base de Données"],["Entité","éléments homogènes partageant des caractéristiques"]]},{"title":"Bases relationnelles et non relationnelles","type":"cards","items":[["Relationnelles","tables liées, langage SQL"],["Non relationnelles","structures variées, notamment bases NoSQL"],["SGBD connus","Oracle Database et Microsoft SQL Server"]]},{"title":"Vocabulaire relationnel","type":"list","numbered":false,"items":["Entité = table","individu = ligne/enregistrement","propriété = colonne/attribut","identifiant unique = clé primaire."]},{"title":"Cardinalités","type":"list","numbered":false,"items":["1:1 : un à un","1:N : un à plusieurs","N:N : plusieurs à plusieurs. Dans une relation 1:N, la clé primaire du côté « un » devient généralement clé étrangère du côté « plusieurs »."]},{"title":"ACS","type":"text","text":"Analyse et Conception des Systèmes d’Information. Analyse : examiner l’existant. Conception : définir la future application."},{"title":"Protection et stockage","type":"text","text":"Backup : copie de sauvegarde pour restaurer les données. Mirroring : duplication/réplication pour améliorer la disponibilité. Stockage interne ou externe, notamment dans le cloud."}],[{"title":"Le SI, système nerveux de l’entreprise","type":"text","text":"Le SI facilite la circulation rapide de l’information, la coordination, la prise de décision et la disponibilité de la bonne information au bon moment. Les organisations utilisent des SI depuis bien avant l’informatique moderne."},{"title":"Les trois sous-systèmes","type":"text","text":"Pilotage/décision : fixe les objectifs. Système d’information : intermédiaire. Système opérationnel : exécute les activités. L’entreprise s’adapte à son environnement pour atteindre ses objectifs, notamment de rentabilité."},{"title":"Les quatre fonctions du SI","type":"list","numbered":false,"items":["Collecter et enregistrer","mémoriser et stocker","traiter","diffuser."]},{"title":"Numérisation, informatisation, digitalisation, automatisation","type":"cards","items":[["Numérisation","transformer le papier en fichier numérique"],["Informatisation","employer des solutions informatiques"],["Digitalisation","transformer les processus grâce au numérique"],["Automatisation","exécuter automatiquement des tâches"]]},{"title":"Objectifs de l’informatisation","type":"list","numbered":false,"items":["Meilleur service","productivité","traçabilité","sécurité","amélioration des conditions de travail."]},{"title":"Fonctions informatisées","type":"cards","items":[["Finance","comptabilité, paie, facturation"],["Gestion commerciale","CRM (Customer Relationship Management), SIM (Système d’Information Marketing)"],["Ressources humaines","SIRH (Système d’Information des Ressources Humaines), suivi du personnel et des carrières"]]},{"title":"Front office et back office","type":"cards","items":[["Front office","activités en contact direct avec les clients"],["Back office","activités et processus internes"]]},{"title":"Frontend et backend","type":"cards","items":[["Frontend","interface visible d’un site web"],["Backend","logique, données et traitements côté serveur"]]}],[{"title":"Définition de l’ERP","type":"list","numbered":false,"items":["ERP = Enterprise Resource Planning","PGI = Progiciel de Gestion Intégré. Programme : instructions","logiciel : programmes et ressources","progiciel : logiciel standardisé destiné à plusieurs utilisateurs ou entreprises. L’ERP intègre plusieurs fonctions de gestion."]},{"title":"Fonctions de l’ERP","type":"list","numbered":false,"items":["Production","planification","fabrication","traçabilité","maintenance","qualité","comptabilité","finance","achats","stocks","ventes","ressources humaines."]},{"title":"Avantages","type":"list","numbered":false,"items":["Base de données commune","cohérence","intégrité","réduction de la redondance","interface intégrée","maintenance coordonnée","globalisation de l’information."]},{"title":"Inconvénients","type":"list","numbered":false,"items":["Coût élevé","couverture imparfaite des besoins","fonctions parfois superflues","nécessité de comprendre les processus","adaptation et formation des utilisateurs."]},{"title":"ERP commerciaux et open source","type":"text","text":"Solutions propriétaires : SAP, Microsoft Dynamics, Oracle E-Business Suite et PeopleSoft. Oracle E-Business Suite et PeopleSoft appartiennent toutes deux à Oracle. Odoo : édition Community open source et édition Enterprise commerciale."},{"title":"FSF et quatre libertés","type":"text","text":"Free Software Foundation. Liberté 0 : utiliser pour tout usage. Liberté 1 : étudier et modifier le code source. Liberté 2 : partager des copies. Liberté 3 : distribuer des versions modifiées. Libre ne signifie pas nécessairement gratuit ; une licence s’applique."},{"title":"Modèles économiques","type":"list","numbered":false,"items":["Fonctionnalités avancées payantes","installation","paramétrage","formation","maintenance","assistance technique."]},{"title":"Évolution des SI","type":"text","text":"Mobilité : smartphones et tablettes. Réseaux : 3G, 4G, 5G et Wi-Fi. Objets connectés (IoT). Cloud computing : ressources et applications accessibles à distance."}],[{"title":"Définition du Cloud Computing","type":"text","text":"Le cloud (informatique en nuage) permet d’utiliser, via Internet, des ressources informatiques hébergées sur des serveurs distants. Ces ressources sont généralement disponibles à la demande."},{"title":"Les trois niveaux du cloud","type":"stack","items":[["IaaS (Infrastructure as a Service)","serveurs, stockage et réseau"],["PaaS (Platform as a Service)","plateforme pour développer et exécuter des applications"],["SaaS (Software as a Service)","logiciels accessibles en ligne et gérés par le fournisseur"]]},{"type":"example","title":"s de services","rows":["Google Workspace (anciennement Google Apps), Dropbox, iCloud, OpenDrive et services cloud d’Amazon."]},{"title":"Comparaison avec un système interne","type":"cards","items":[["Système interne","l’entreprise gère son infrastructure et ses logiciels"],["IaaS","le fournisseur gère l’infrastructure et la virtualisation"],["PaaS","il gère aussi la plateforme d’exécution"],["SaaS","il gère le logiciel, son fonctionnement et sa maintenance"]]},{"title":"Avantages du cloud","type":"list","numbered":false,"items":["Ressources à la demande","paiement pouvant dépendre de la consommation, des utilisateurs et des fonctionnalités","installation réduite pour les applications web","accès depuis plusieurs appareils","mobilité","sauvegardes pouvant limiter certaines pertes de données locales."]},{"title":"Limites et risques du cloud","type":"cards","items":[["Perte de contrôle","données et logiciels hébergés chez un fournisseur externe"],["Confidentialité","lire les politiques de confidentialité et les conditions d’utilisation"],["Suppression des données","vérifier les règles de conservation et de suppression appliquées par le fournisseur"]]}],[{"title":"Définition d’un processus métier","type":"text","text":"Un processus métier est un enchaînement organisé d’activités réalisées par des acteurs aux rôles prédéfinis afin d’atteindre un résultat précis. Il possède un début, une fin et une sortie mesurable."},{"title":"Caractéristiques d’un processus","type":"list","numbered":false,"items":["Un début et une fin","une entrée et une sortie mesurables","une valeur ajoutée","une capacité à être reproduit. Un processus est généralement répétable, contrairement à une activité ponctuelle."]},{"title":"Trois niveaux de processus","type":"stack","items":[["Processus de haut niveau","grandes activités de l’entreprise"],["Processus intermédiaire","principales étapes"],["Processus élémentaire","activités les plus simples"]]},{"title":"Digitalisation des processus métier","type":"text","text":"Les processus peuvent être découpés en tâches élémentaires, réalisées manuellement ou par des machines. Les SI permettent de modéliser et de suivre les processus, et de conserver des traces des opérations."},{"title":"Traçabilité","type":"text","text":"Les informations enregistrées permettent de savoir qui a réalisé une tâche, quand et pourquoi, lorsque ces éléments sont renseignés dans le SI."},{"title":"Définition du Workflow","type":"text","text":"Le workflow est l’automatisation de la totalité ou d’une partie d’un processus métier, conformément à des règles prédéfinies. Il permet d’exécuter les processus métier en organisant les tâches. Un schéma est préparé avant l’exécution."},{"title":"Aspects opérationnels du workflow","type":"list","numbered":false,"items":["Séquence des tâches et acteurs responsables","circulation des données","mécanismes de suivi, de mesure et de contrôle des activités."]},{"title":"Workflow Management et BPM","type":"cards","items":[["Workflow Management","gestion et suivi des workflows"],["BPM (Business Process Management)","analyse, gestion et amélioration des processus pour repérer retards et problèmes"]]},{"title":"Intérêt de l’automatisation","type":"text","text":"Au-delà du gain de temps : collecte et stockage d’informations, disponibilité des données, traçabilité, analyse en temps réel et transparence. Cette transparence peut entraîner une résistance au changement."},{"title":"Fonctionnalités et gains d’un système workflow","type":"list","numbered":false,"items":["Suivre et analyser les activités","améliorer l’efficacité des opérations","favoriser l’amélioration continue","faciliter la circulation et le stockage des informations","aider aux décisions stratégiques, tactiques et opérationnelles","améliorer les services aux clients."]}],[{"title":"Avantages de l’utilisation d’un système Workflow","type":"list","numbered":false,"items":["Diminution des pertes et des coûts d’exploitation","augmentation de la rentabilité","détection des activités à forte valeur ajoutée","amélioration de l’efficience et de l’efficacité des processus","meilleure réponse aux besoins des clients internes et externes, avec une satisfaction et une fidélité accrues","accès à des données et informations fiables","définition claire des responsabilités et des tâches","collaboration et travail d’équipe","réduction des erreurs humaines","aide à la prise de décision et à l’amélioration continue."]},{"title":"Règle de Pareto (80/20)","type":"text","text":"Le principe de Pareto indique qu’environ 80 % des effets peuvent provenir de 20 % des causes. Exemple : une petite partie des activités peut créer la majorité de la valeur. Dans un workflow, cette règle aide à repérer les activités prioritaires à améliorer. Les proportions sont indicatives, pas systématiques."},{"title":"LLM et agents IA","type":"text","text":"LLM signifie Large Language Model (grand modèle de langage). Un agent IA peut utiliser un modèle et des outils pour réaliser des tâches. Exemples cités dans le cours : n8n, Zapier, Dify, CrewAI et Lindy."},{"title":"Fonctionnalités nécessaires d’un logiciel d’automatisation de Workflow","type":"list","numbered":true,"items":["Utilisation d’une notation internationale standardisée, BPMN (Business Process Model and Notation), pour représenter les processus métier","Création facile de règles et d’intégrations","Accès à distance et partage en temps réel grâce au cloud","Gestion des échéances et des alertes","Portabilité sur ordinateur, smartphone et tablette","Infrastructure cloud pour réduire certaines tâches techniques et les coûts associés. 7. Automatisation de la gestion de l’entreprise, élimination des flux inutiles et analyse des KPI en temps réel."]}],[{"title":"Définition du BPMN","type":"text","text":"BPMN (Business Process Model and Notation) est un langage graphique standardisé de modélisation des processus métiers. Il décrit les chaînes de valeur, les activités et leur enchaînement dans une organisation."},{"title":"Autres méthodes et langages","type":"text","text":"UML et Merise sont également cités comme autres approches de modélisation des systèmes d’information et des données ; ils ne sont pas développés dans ce cours."},{"title":"Trois modèles BPMN","type":"text","text":"Modèle de processus : activités et enchaînements d’un processus, notamment interne. Modèle de collaboration : processus de plusieurs entités et échanges entre elles. Modèle de chorégraphie : interactions et comportements attendus des participants. Le cours se concentre sur le modèle de processus."},{"title":"A. Piscines et couloirs","type":"text","text":"Piscine (pool) : limite définissant l’environnement d’un participant au processus. Couloir (lane) : subdivision d’une piscine, par exemple un service ou un rôle ; les couloirs peuvent être subdivisés. Les tâches peuvent se succéder entre couloirs d’une même piscine."},{"title":"B. Activités","type":"text","text":"Une activité est un ensemble de tâches répétitives. Une tâche est une action qu’un participant au processus réalise, parmi d’autres tâches exécutées les unes après les autres, afin d’atteindre un objectif défini du processus métier. Les tâches sont associées aux couloirs et nommées généralement avec un verbe à l’infinitif et un complément. Les flèches de flux de séquence indiquent leur ordre d’exécution."},{"title":"C. Événements","type":"text","text":"Les événements indiquent que quelque chose se produit pendant un processus. Événement de début : ce qui déclenche le processus (cercle simple). Événement intermédiaire : changement ou interaction affectant son déroulement (double cercle). Événement de fin : clôture du processus (cercle à bord épais)."},{"type":"example","title":"récapitulatif","rows":["Dans une entreprise : recevoir une demande → vérifier le dossier → valider la demande.","Chaque tâche peut être attribuée à un couloir","les flèches représentent les flux de séquence.","Le processus commence par un événement de début et se termine par un événement de fin."]}]],"fiscalite":[[{"title":"Droit fiscal et fiscalité","type":"cards","items":[["Droit fiscal","règles relatives à l’établissement, la collecte et au paiement des impôts"],["Fiscalité","application pratique et technique du droit fiscal"]]},{"title":"Définition de la TVA","type":"text","text":"Taxe sur la Valeur Ajoutée : taxe sur le chiffre d’affaires applicable notamment aux opérations industrielles, commerciales, artisanales, aux professions libérales, aux importations et aux opérations de l’article 89 du CGI."},{"title":"TVA facturée, récupérable et déductible","type":"cards","items":[["TVA facturée","TVA sur les ventes imposables"],["TVA récupérable","TVA supportée sur des achats susceptibles d’ouvrir droit à déduction"],["TVA déductible","TVA dont les conditions légales de déduction sont remplies"]]},{"title":"Les sept catégories d’opérations","type":"list","numbered":true,"items":["Hors champ","Exonérées sans droit à déduction","Exonérées avec droit à déduction","Obligatoirement imposables sans droit à déduction sur les achats concernés","Obligatoirement imposables avec droit à déduction","Imposables par option","Opérations en suspension de TVA."]},{"title":"À retenir","type":"tip","text":"Les exonérations avec droit à déduction permettent une récupération sous conditions. La suspension est un régime particulier. Le droit à déduction dépend toujours des conditions légales."}],[{"title":"TVA facturée","type":"text","text":"TVA appliquée aux ventes imposables. L’entreprise et l’opération doivent relever de la TVA."},{"title":"Régime des débits","type":"text","text":"Régime optionnel : TVA exigible dès l’inscription de la créance en comptabilité, même avant encaissement, sous réserve des règles applicables aux encaissements anticipés."},{"title":"Régime des encaissements","type":"text","text":"TVA exigible à l’encaissement effectif : en totalité en cas d’encaissement total, proportionnellement en cas d’encaissement partiel."},{"title":"TVA déductible","type":"text","text":"TVA sur les achats admissibles, sous conditions. Selon les règles étudiées, un décaissement partiel peut entraîner une déduction proportionnelle. Certaines dépenses sont exclues par l’article 106."},{"title":"Moyens de paiement : repères du cours","type":"cards","items":[["Espèces","paiement immédiat"],["effet de commerce","échéance sous réserve d’encaissement"],["chèque et virement","crédit effectif"],["paiement électronique","réception des fonds"],["chèque certifié","demande de certification selon règle particulière"],["compensation","date de compensation"]]},{"title":"Prudence juridique","type":"tip","text":"Les dates d’effectivité dépendent du régime et des règles applicables au paiement concerné."}],[{"title":"Rappel : TVA et droit à déduction","type":"cards","items":[["TVA facturée","taxe collectée sur les ventes imposables ; TVA récupérable : taxe supportée sur les achats admissibles ; TVA due (simplifiée) = TVA facturée − TVA déductible, après crédits et ajustements éventuels"],["Opérations","imposables et exonérées avec droit à déduction ; exonérées sans droit et hors champ sans droit à déduction"]]},{"title":"Pourquoi un prorata ?","type":"text","text":"Une entreprise exerçant à la fois des activités ouvrant droit à déduction et des activités sans droit doit répartir la TVA grevant ses dépenses communes. Le prorata de déduction (PD) exprime la part admise en déduction. Les dépenses affectées exclusivement à une activité et les exclusions légales suivent leurs règles propres."},{"title":"Calcul du prorata","type":"formula","lead":"","formula":"PD = A ÷ (A + B) × 100","text":"A : chiffre d’affaires ouvrant droit à déduction, incluant les opérations exonérées avec droit ou en suspension et les taxes théoriques prévues par l’article 104-I ; B : opérations exonérées sans droit ou hors champ, selon les montants retenus légalement. Exemple simplifié : A = 800 000 DH, total = 1 000 000 DH → PD = 80 %."},{"title":"Prorata réel et provisoire","type":"text","text":"Le prorata calculé à la fin de l’année N à partir des opérations réalisées sert à calculer la TVA déductible en N+1. Exemple : prorata réel 2025 = 80 % → prorata utilisé en 2026 = 80 %. Règles particulières pour les entreprises nouvelles (article 104-I)."},{"title":"TVA déductible sur les achats","type":"formula","lead":"Pour une dépense commune admissible","formula":"TVA déductible = TVA sur facture × PD","text":"D’abord vérifier la nature de la dépense et le droit légal à déduction, puis appliquer le prorata lorsqu’il est requis."},{"type":"example","title":"matières premières","rows":["Achat 360 000 DH TTC, TVA 20 %, PD 85 %.","TVA = 360 000 ÷ 1,20 × 20 % = 60 000 DH","TVA déductible = 60 000 × 85 % = 51 000 DH","part non déductible = 9 000 DH.","Exemple du cours : application du prorata supposée."]},{"type":"example","title":"fournitures de bureau","rows":["Achat 12 000 DH TTC, TVA 20 %, PD 80 %.","TVA = 12 000 ÷ 1,20 × 20 % = 2 000 DH","TVA déductible = 2 000 × 80 % = 1 600 DH."]},{"type":"example","title":"voiture de tourisme","rows":["Achat 480 000 DH TTC.","Pour une voiture de tourisme ordinaire frappée d’exclusion légale (article 106), la TVA déductible est nulle, même si le prorata est élevé.","Les exceptions légales éventuelles doivent être examinées."]},{"title":"Défaut de conservation : principe","type":"text","text":"Article 102 : conservation des biens meubles immobilisés pendant 60 mois et des immeubles pendant 10 ans, sous réserve des exceptions. Une cession, un retrait ou un changement d’affectation prématuré peut entraîner un reversement (article 104-II-2°). Le mois d’acquisition et de sortie d’un meuble compte comme mois entier ; l’année compte comme année entière pour les immeubles."},{"title":"Défaut de conservation : exemple","type":"list","numbered":false,"items":["Matériel meuble, TVA initialement déduite = 40 000 DH","acquisition 01/01/2026","sortie 31/12/2026","12 mois retenus et 48 mois restant sur 60. TVA conservée = 40 000 × 12/60 = 8 000 DH","TVA à reverser = 40 000 × 48/60 = 32 000 DH, sous réserve des règles propres à la cession."]},{"title":"Variation du prorata : seuil","type":"list","numbered":false,"items":["Pour les biens immobilisés et dans la période légale de cinq années, comparer PR (prorata réel) et PP (prorata initial). Si PR − PP > +5 points : déduction complémentaire possible","si PR − PP < −5 points : reversement obligatoire","si l’écart est compris entre −5 et +5 points inclus : pas de régularisation à ce titre (article 104-II-1°)."]},{"title":"Variation : hausse du prorata","type":"list","numbered":false,"items":["TVA sur immobilisation = 420 000 DH","PP = 90 %","PR = 97 %","écart = +7 points. Déduction complémentaire = 420 000 × (97 % − 90 %) ÷ 5 = 5 880 DH."]},{"title":"Variation : baisse du prorata","type":"list","numbered":false,"items":["TVA sur immobilisation = 420 000 DH","PP = 90 %","PR = 80 %","écart = −10 points. Reversement = 420 000 × (90 % − 80 %) ÷ 5 = 8 400 DH."]},{"title":"Comparaison des régularisations","type":"list","numbered":false,"items":["Défaut de conservation : sortie anticipée du bien","calcul selon fraction de période restante","généralement reversement. Variation du prorata : changement de plus de cinq points du prorata d’une immobilisation pendant la période de régularisation","déduction complémentaire ou reversement selon le sens de la variation. Ne pas confondre ces mécanismes."]},{"title":"Références fiscales","type":"ref","text":"Code général des impôts marocain, édition 2026 : articles 102 (biens amortissables), 104-I (prorata), 104-II (régularisations) et 106 (exclusions). Cours pédagogique ; vérifier les cas particuliers et l’année fiscale applicable."}],[{"title":"Formule principale","type":"formula","lead":"","formula":"TVA nette = TVA exigible − TVA déductible","text":"Il faut aussi tenir compte des crédits antérieurs et des ajustements éventuels."},{"title":"TVA due et crédit de TVA","type":"cards","items":[["Solde positif","TVA due"],["Solde négatif","crédit de TVA, généralement reportable selon les dispositions applicables"]]},{"title":"Moyens de paiement admis étudiés","type":"text","text":"Virement bancaire, compensation, chèque bancaire non endossable, effet de commerce. D’autres moyens peuvent être admis par l’article 106."},{"title":"Plafonds de l’article 106","type":"text","text":"Pour certains règlements par des moyens non admis : 5 000 DH par jour et par fournisseur, 50 000 DH par mois et par fournisseur. Ces montants portent sur les achats réglés et non directement sur la TVA."},{"title":"TVA incluse dans le TTC","type":"formula","lead":"","formula":"TVA = TTC ÷ (1 + taux) × taux","text":"Exemple : 5 000 DH TTC à 20 % donnent 833,33 DH de TVA."},{"title":"Périodicité de déclaration","type":"text","text":"Règle générale : mensuelle si chiffre d’affaires taxable de l’année précédente ≥ 1 000 000 DH ; trimestrielle si inférieur à 1 000 000 DH. Exceptions et options légales possibles."}]],"tec":[[{"title":"Communiquer efficacement : de l'information à l'action","type":"text","text":"Une information exacte n'est pas automatiquement une communication efficace. Une instruction peut être vraie, mais trop vague pour être comprise et exécutée. La communication professionnelle doit permettre au destinataire de comprendre ce qui est attendu, pourquoi, comment, et dans quel délai.\n\nLe cours distingue trois étapes :\n\n1. Transmettre : communiquer une information vérifiable et pertinente.\n2. Adapter : choisir le vocabulaire, les détails, le canal et le ton selon la personne et la situation.\n3. Faire agir / coordonner : rendre possible une réponse, une décision ou une action.\n\nCas professionnel : « Le nouvel outil sera utilisé lundi. Faites le nécessaire. » Ce message laisse ouvertes plusieurs questions : qui doit agir ? Quelle tâche ? À quel moment ? Où obtenir de l'aide ?\n\nReformulation proposée : « À partir de lundi, l'équipe utilisera le nouveau logiciel. Avant vendredi à 17 h, chaque collaborateur devra activer son compte à partir du lien reçu par courriel. La démonstration aura lieu jeudi à 14 h. » Cette version précise la tâche, le responsable, l'échéance et l'accompagnement."},{"title":"Qu'est-ce que communiquer ? Information et communication","type":"text","text":"Communiquer est un processus dans lequel des personnes construisent, transmettent, interprètent et partagent un sens en fonction d'une situation. La communication n'est donc pas seulement l'envoi d'une phrase : elle implique la manière dont celle-ci est comprise et la possibilité d'une réaction.\n\nNotion — Définition utile — Exemple.\nDonnée / information — Fait ou résultat transmis — « Le délai de réponse moyen est de 48 heures. ».\nCommunication professionnelle — Information mise en contexte pour un destinataire, avec une intention et une possibilité de retour — « Le délai moyen est de 48 heures : nous devons analyser les retards et proposer une amélioration. ».\nInterprétation — Sens donné au message par le récepteur — Deux services peuvent comprendre différemment « urgent »..\nRétroaction (feedback) — Réponse indiquant la réception, la compréhension ou la réaction au message — « D'accord, je prépare le tableau avant 16 h. ».\n\nChaîne d'utilisation : donnée → information → interprétation → décision / action. Il s'agit d'un repère pédagogique : la communication n'est pas opposée à l'information, elle en organise l'usage dans une relation."},{"title":"Analyser une situation de communication","type":"text","text":"Le schéma enseigné comporte sept composantes principales, situées dans un contexte.\n\nComposante — Question de contrôle — Exemple d'un chef d'équipe.\nÉmetteur — Qui prend l'initiative ? — Responsable d'agence.\nIntention — Dans quel but ? — Faire appliquer une procédure.\nMessage — Quel contenu ? — « Vérifiez les dossiers incomplets. ».\nCanal et code — Par quel moyen et avec quel langage ? — Réunion ; français professionnel.\nRécepteur — À qui s'adresse-t-on ? — Conseillers clientèle.\nInterprétation — Comment le message est-il compris ? — Vérifier uniquement certains dossiers, ou tous ?.\nRétroaction — Comment savoir si le message est compris ? — Question, reformulation ou compte rendu.\n\nContexte transversal : lieu, moment, situation, relation entre interlocuteurs, contraintes et objectif. Le canal et le code sont regroupés dans une composante du schéma du professeur ; on peut les distinguer en détail lors de l'analyse.\n\nMéthode d'examen : pour analyser un message, identifier d'abord les sept composantes, puis repérer une éventuelle ambiguïté et proposer une reformulation mesurable."},{"title":"Trois repères théoriques","type":"text","text":"A. Shannon et Weaver : la transmission et le bruit.\n\nLe modèle met l'accent sur l'acheminement de l'information entre une source et une destination par un canal. Un bruit peut perturber cette transmission. Dans des situations professionnelles, la notion de perturbation est appliquée à une mauvaise connexion, à un document illisible ou, plus largement, à un message mal compris.\n\nLimite à connaître : ce modèle est d'abord un modèle de transmission de l'information ; il ne suffit pas à expliquer, à lui seul, toute la construction du sens dans un échange humain.\n\nB. Jakobson : les six fonctions du langage.\n\nFonction — Ce qu'elle met en avant — Exemple original.\nRéférentielle — Donner une information sur une situation — « La réunion commence à 10 h. ».\nExpressive (émotive) — Faire apparaître l'attitude ou le ressenti de l'émetteur — « Je suis inquiet du retard. ».\nConative — Orienter la réaction ou l'action du destinataire — « Transmettez le rapport aujourd'hui. ».\nPhatique — Ouvrir, vérifier ou maintenir le contact — « Vous m'entendez bien ? ».\nMétalinguistique — Expliquer le code ou le sens d'un terme — « Par KPI, nous entendons indicateur de performance. ».\nPoétique — Mettre en valeur la forme du message — « Plus simple, plus rapide, plus proche. ».\n\nAttention : un même message peut remplir plusieurs fonctions ; dans un exercice, on cherche généralement sa fonction dominante.\n\nC. Approche interactionnelle.\n\nLe destinataire n'est pas passif : il réagit, questionne, reformule et contribue à construire le sens. Une communication efficace demande donc de l'écoute, de l'adaptation et de la rétroaction."},{"title":"Les enjeux de la communication","type":"text","text":"Le professeur met en avant plusieurs finalités qui peuvent coexister : informer, expliquer, convaincre, coopérer, négocier et entretenir la relation.\n\n- Informer : partager un fait utile à la décision.\n- Expliquer : rendre un mécanisme ou une procédure compréhensible.\n- Convaincre : soutenir une proposition par des arguments adaptés.\n- Coopérer : organiser l'action de plusieurs personnes.\n- Négocier : chercher un accord malgré des intérêts ou contraintes différents.\n- Entretenir la relation : maintenir la confiance et limiter les malentendus.\n\nExemple : annoncer un retard = informer ; présenter les causes = expliquer ; justifier un nouveau calendrier = convaincre ; répartir les tâches = coopérer."},{"title":"Adapter le message au destinataire","type":"text","text":"Une même situation ne se présente pas de la même façon à un spécialiste, à un responsable et à un client.\n\nSituation : le portail client d'une banque est indisponible.\n\nDestinataire — Formulation adaptée.\nÉquipe technique — « Des erreurs serveur bloquent l'authentification ; vérifiez les journaux de connexion. ».\nDirection — « Une panne empêche temporairement certains clients de se connecter ; une intervention est en cours. ».\nClient — « L'accès au service est temporairement perturbé. Nos équipes travaillent à le rétablir. ».\n\nOn adapte le contenu, le vocabulaire, le degré de détail, le canal et le ton. Adapter ne signifie pas dissimuler les faits ; cela consiste à rendre le message utile à son destinataire."},{"title":"Obstacles et formes de communication","type":"text","text":"Les huit obstacles du support.\n\n1. Ambiguïté : « Faites le nécessaire » ne décrit aucune tâche concrète.\n2. Jargon : des termes techniques sans explication excluent le destinataire.\n3. Information insuffisante : l'action et le délai sont absents.\n4. Excès d'information : l'essentiel se perd dans des détails.\n5. Mauvais canal : une urgence diffusée uniquement par un canal peu consulté.\n6. Mauvais destinataire : un message envoyé à une personne qui ne peut pas agir.\n7. Absence de rétroaction : aucune vérification de la compréhension.\n8. Bruit / émotion : distraction, problème de son, tension ou ton agressif.\n\nCommunication orale et écrite.\n\n- Orale : réunions, entretiens, négociations, présentations. Elle combine le verbal, le paraverbal et le non-verbal (développés au chapitre 2).\n- Écrite : courriels, rapports, notes, comptes rendus. Elle nécessite clarté, structure et précision, même sans voix ni gestes."},{"title":"Cas d'application corrigé — déploiement d'un logiciel","type":"text","text":"Situation : un manager annonce : « Nous changeons de logiciel lundi. Préparez-vous. » L'équipe demande s'il faut installer un programme, activer un compte ou suivre une formation.\n\nDiagnostic : intention identifiable, mais message incomplet : action attendue, modalité, délai et assistance non précisés. L'émetteur ne vérifie pas la compréhension.\n\nProposition : « Avant vendredi 16 h, chaque membre de l'équipe active son compte depuis le courriel du service informatique. Une démonstration est prévue jeudi à 11 h. Signalez toute difficulté au responsable. »\n\nPourquoi cette version fonctionne mieux : elle attribue une tâche, fixe un délai, indique un canal d'aide et ouvre la rétroaction."}],[{"title":"Trois dimensions complémentaires","type":"text","text":"Dimension — Définition — À maîtriser.\nVerbal — Ce que l'on dit — Vocabulaire, syntaxe, précision, structure, connecteurs.\nParaverbal — Comment la voix porte les mots — Débit, volume, rythme, intonation, pauses, accentuation.\nNon verbal — Ce que le corps communique — Regard, posture, gestes, expressions faciales, orientation.\n\nExemple : annoncer « Je suis disponible pour répondre aux questions » avec les bras fermés et un ton impatient peut créer un décalage entre le verbal, le paraverbal et le non-verbal.\n\nPrincipe : rechercher la cohérence entre les trois dimensions, sans prétendre qu'un geste aurait toujours une signification unique dans toutes les situations."},{"title":"Se présenter : construire une identité professionnelle","type":"text","text":"Selon le repère inspiré d'Erving Goffman, nous gérons l'impression produite lors des interactions sociales. Le cours propose une progression :\n\nIdentité → parcours → compétences → expériences → projet → positionnement.\n\nMini-présentation adaptée à un étudiant BFA (exemple créé pour Study BFA) :\n\n« Je suis étudiant en Banque, Finance et Assurance. Ma formation m'a permis de travailler sur la comptabilité, l'analyse financière et le fonctionnement des établissements financiers. J'ai également participé à un projet de révision collaborative. Je cherche à développer mes compétences en analyse et à découvrir leur application pendant un stage. »\n\nConseil pratique : pour une présentation de 45 à 60 secondes, choisir les informations pertinentes pour l'interlocuteur, ne pas réciter le CV et terminer par un objectif clair."},{"title":"Quatre intentions communicatives","type":"text","text":"Intention — Question centrale — Situation professionnelle.\nInformer / expliquer — Que doit-on comprendre ? — Présenter les résultats d'une étude.\nArgumenter / convaincre — Pourquoi accepter cette proposition ? — Défendre un nouveau logiciel.\nÉduquer / décrire une procédure — Comment faire concrètement ? — Montrer comment déposer un document.\nCoordonner / décider — Qui fait quoi et quand ? — Répartir les tâches d'un projet.\n\nMéthode : avant de parler, identifier le résultat attendu : comprendre, adhérer, exécuter ou décider. Une intervention peut combiner plusieurs intentions."},{"title":"Les trois piliers de la persuasion","type":"text","text":"Pilier — Sens — Exemple.\nLogos — Raisonnement, arguments et éléments vérifiables — « Le test pilote a réduit le délai moyen de traitement. ».\nEthos — Crédibilité et sérieux de l'orateur — Montrer sa maîtrise du sujet et reconnaître les limites de son analyse.\nPathos — Prise en compte des émotions et préoccupations du public — Évoquer les difficultés concrètes subies par les utilisateurs.\n\nCas : « Nous avons interrogé des utilisateurs et observé des retards » s'appuie surtout sur le logos si l'on fournit des données vérifiables. « Je connais les contraintes de votre équipe » peut soutenir l'ethos ; « Imaginez un client bloqué à un moment urgent » mobilise plutôt le pathos.\n\nNuance : un discours solide peut associer les trois piliers. Un chiffre présenté sans méthode ni preuve ne devient pas automatiquement convaincant."},{"title":"Participer à une réunion et gérer l'échange collectif","type":"text","text":"Parler longtemps ne signifie pas communiquer efficacement. Une intervention utile comprend une idée claire, une justification et un lien avec la discussion.\n\nÉcoute active : laisser terminer l'autre, reformuler fidèlement son idée, poser une question et exprimer un désaccord avec précision plutôt qu'avec agressivité.\n\nTreize expressions professionnelles du cours.\n\nExpression — Signification — Exemple original.\nFaire le point — Examiner la situation actuelle — « Faisons le point sur les dossiers traités. ».\nÊtre à l'ordre du jour — Figurer parmi les sujets prévus — « La sécurité est à l'ordre du jour. ».\nFaire un tour de table — Donner la parole à chacun — « Commençons par un tour de table. ».\nRemettre à plat — Réexaminer un fonctionnement en profondeur — « Remettons à plat notre répartition des tâches. ».\nCadrer le sujet — Définir son périmètre et ses objectifs — « Cadrons le sujet avant de proposer des solutions. ».\nTenir le cap / la barre — Maintenir l'objectif malgré les difficultés — « Malgré le retard, gardons notre objectif. ».\nSuivre l'avancement — Contrôler la progression — « Nous suivrons l'avancement chaque semaine. ».\nMettre à jour — Actualiser les données — « Mettez à jour le tableau des opérations. ».\nPasser la main — Transmettre le relais ou la responsabilité — « L'analyse est finie ; passons la main au contrôle. ».\nArrondir les angles — Atténuer les tensions pour faciliter l'accord — « Essayons d'arrondir les angles. ».\nMettre les bouchées doubles — Redoubler d'efforts — « Nous devons mettre les bouchées doubles pour finir. ».\nJouer cartes sur table — Parler avec franchise — « Jouons cartes sur table sur les coûts. ».\nÊtre dans les temps — Respecter le calendrier — « Le rapport est prêt : nous sommes dans les temps. ».\n\nNe pas confondre : « remettre à plat » (revoir en profondeur) et « mettre à jour » (actualiser) ; « passer la main » (transférer) et « mettre les bouchées doubles » (accélérer son travail)."},{"title":"L'architecture d'un exposé et les étapes du pitch","type":"text","text":"A. Exposé.\n\nIntroduction : contextualiser, présenter la problématique et annoncer le plan.  \nDéveloppement : présenter les idées principales et les appuyer par des exemples et des arguments.  \nConclusion : répondre à la problématique, synthétiser et préciser les limites ou ouvertures.\n\nUn thème n'est pas une problématique. Thème : « Les réseaux sociaux dans les entreprises ». Problématique possible : « Dans quelles conditions les réseaux sociaux améliorent-ils la relation client sans dégrader la confiance ? »\n\nB. Pitch : six étapes du support.\n\n1. Problème : quelle difficulté veut-on résoudre ?\n2. Objectif : quel résultat cherche-t-on ?\n3. Solution : que propose-t-on concrètement ?\n4. Résultats attendus : quels effets et quels indicateurs ?\n5. Risques : quelles contraintes faut-il anticiper ?\n6. Décision attendue : que demande-t-on au public à la fin ?\n\nApplication Study BFA (illustration, non tirée du professeur) : problème de dispersion des ressources → objectif de révision plus accessible → plateforme de cours et de quiz → mesure d'utilisation et retours → risques de mise à jour et de fiabilité → demande d'autorisation pour présenter le projet aux étudiants."},{"title":"Assurer la cohérence : connecter les idées","type":"text","text":"Une succession de phrases correctes n'est pas forcément un discours cohérent. Les connecteurs permettent de faire percevoir la relation logique.\n\nConnecteur — Relation logique — Exemple.\nToutefois — Opposition / réserve — « Le logiciel est efficace. Toutefois, son coût doit être étudié. ».\nPremièrement, ensuite, enfin — Ordre / hiérarchie — « Premièrement, évaluons le besoin ; ensuite, testons la solution. ».\nDonc — Conséquence — « Le délai augmente ; nous devons donc revoir la procédure. ».\n\nExercice résolu : « La plateforme simplifie le suivi. Toutefois, son coût est important et les salariés doivent être formés. Nous devons donc évaluer ces contraintes avant de décider. »"},{"title":"Expliquer, argumenter et répondre aux objections","type":"text","text":"A. Expliquer pour faire agir.\n\nUne procédure utile comprend des verbes d'action, un ordre clair, des conditions d'accès et une vérification finale.\n\nConsigne insuffisante : « Mettez le document dans l'espace de travail et partagez-le. »\n\nConsigne claire : « Connectez-vous à la plateforme, ouvrez le dossier du projet, déposez le fichier, vérifiez les autorisations d'accès, puis copiez le lien de partage. »\n\nB. Argumenter plutôt que simplement affirmer.\n\nStructure du cours : thèse → argument → preuve / donnée → conclusion ou limite.\n\n- Thèse : « Nous devrions tester un nouvel outil de suivi. »\n- Argument : « Il pourrait centraliser les demandes. »\n- Preuve à rechercher : comparer les délais de traitement avant et après un test pilote.\n- Conclusion prudente : « Si le test confirme le gain, nous pourrons envisager le déploiement. »\n\nÀ retenir : l'affirmation n'est pas une preuve ; une hypothèse doit être vérifiée.\n\nC. Traiter une objection de façon professionnelle.\n\nLe support utilise l'expression neutraliser une objection. Dans ce chapitre, nous l'entendons comme écouter, reconnaître la préoccupation et répondre par une solution ou une preuve, et non comme ignorer le désaccord.\n\nTrois étapes :\n\n1. Écoute / reformulation : « Vous craignez que le coût soit trop élevé. »\n2. Reconnaissance : « Cette contrainte budgétaire mérite d'être examinée. »\n3. Redirection argumentée : « Nous pouvons tester une version pilote et comparer son coût au temps économisé. »\n\nAutres objections possibles : résistance au changement, protection des données, intérêt de remplacer l'ancien système. Répondre avec une mesure adaptée, et non une promesse non justifiée."},{"title":"Maîtriser la dynamique d'exécution","type":"text","text":"Le cours rassemble trois axes :\n\n- Maîtrise du temps : hiérarchiser les idées ; consacrer la durée nécessaire aux points essentiels ; terminer à l'heure.\n- Maîtrise de la voix / du débit : parler assez lentement pour être compris, marquer les pauses, respirer et accentuer les mots-clés.\n- Maîtrise de la réunion : cadrer l'échange, rappeler les critères d'une décision, faire progresser la discussion et conclure sur les prochaines actions.\n\nExemple : au lieu de répéter « Nous devons choisir vite », dire « Il nous reste dix minutes ; comparons les deux solutions sur le coût et la sécurité, puis retenons l'étape suivante. »"},{"title":"Cas de synthèse corrigé — plateforme collaborative","type":"text","text":"Situation : un étudiant défend l'adoption d'une plateforme de travail. Un responsable lui répond : « C'est trop cher, et les équipes ne seront pas formées. »\n\nRéponse faible : « Ce projet est excellent, faites-moi confiance. »\n\nRéponse structurée : « Je comprends vos réserves sur le budget et la formation. Nous pourrions commencer par un test avec une équipe volontaire ; son coût serait limité et nous mesurerions la durée de traitement des demandes. Après ce test, nous comparerions les résultats et déciderions de poursuivre ou non. »\n\nAnalyse : reformulation de l'objection (écoute) ; solution progressive (redirection) ; indicateurs à mesurer (logos) ; prudence sur les résultats (ethos)."}],[{"title":"Qualités de l’écrit","type":"list","numbered":false,"items":["Ponctuation","cohérence et cohésion","registre de langue","type de discours","mise en page. L’écrit doit être lisible et adapté à son destinataire."]},{"title":"Curriculum vitæ (CV)","type":"text","text":"Document qui présente de manière organisée le parcours, les formations, les compétences et les expériences d’un candidat."},{"title":"Rubriques du CV","type":"list","numbered":false,"items":["Coordonnées : nom, téléphone et courriel","diplômes et formations","expériences professionnelles","langues et logiciels maîtrisés","centres d’intérêt pertinents."]},{"title":"Ordre antéchronologique","type":"text","text":"Présenter les formations et expériences de la plus récente à la plus ancienne."},{"title":"Présentation d’une formation","type":"flow","parts":["Date","intitulé du diplôme ou de la certification","institution","ville","pays","mention, si elle existe"]},{"type":"example","title":"de formation","rows":["2020 — Certification en communication digitale","Université de Lille","Lille, France","Mention : Bien.","Exemple de présentation, non une certification personnelle."]},{"title":"Style du CV","type":"text","text":"Préférer des intitulés courts et professionnels, sans articles superflus : « Responsable de projets digitaux » plutôt qu’une phrase complète."}]]};
(function(){'use strict';
function el(t,c,x){var e=document.createElement(t);if(c)e.className=c;if(x!==undefined)e.textContent=x;return e}
function render(b){var t=b.type,w=el('section','sb-b sb-'+t);
if(t==='tip'){w.append(el('strong','',b.title),el('p','',b.text));return w}
if(t==='ref'){w.append(el('p','',b.text));return w}
if(b.title)w.append(el('h4','sb-h',b.title));
if(t==='text')w.append(el('p','',b.text));
else if(t==='formula'){if(b.lead)w.append(el('p','sb-lead',b.lead));w.append(el('div','sb-formula',b.formula));if(b.text)w.append(el('p','sb-note',b.text))}
else if(t==='example'){w.prepend(el('h4','sb-h','Exemple'+(b.title?' · '+b.title:'')));var u=el('div','sb-ex');b.rows.forEach(function(r,i){var p=el('p',i?'':'sb-given'),k=r.lastIndexOf('=');if(i&&k>0)p.append(document.createTextNode(r.slice(0,k+1)+' '),el('b','',r.slice(k+1).trim()));else p.textContent=r;u.append(p)});w.append(u)}
else if(t==='flow'){var f=el('div','sb-flow');b.parts.forEach(function(x,i){if(i)f.append(el('i','','→'));f.append(el('span','',x))});w.append(f)}
else if(t==='list'){var l=el(b.numbered?'ol':'ul','sb-list');b.items.forEach(function(x){l.append(el('li','',x))});w.append(l)}
else{var g=el('div','sb-grid');b.items.forEach(function(it,i){var c=el('div','sb-card sb-c'+i);c.append(el('b','',it[0]),el('span','',it[1]));g.append(c)});w.append(g)}
return w}
function mount(root){var d=window.STUDY_BFA_SHEETS,slug=document.body.dataset.matiere;if(!d||!d[slug])return;
var i=[].slice.call(document.querySelectorAll('[data-ai-chapter]')).findIndex(function(b){return b.classList.contains('active')});if(i<0)i=0;
var s=d[slug][i];if(!s)return;if(root.firstElementChild&&root.firstElementChild.classList.contains('sb-sheet')&&root.dataset.sbIdx===String(i))return;
var sh=el('div','sb-sheet');s.forEach(function(b){sh.append(render(b))});root.dataset.sbIdx=i;root.replaceChildren(sh)}
document.addEventListener('DOMContentLoaded',function(){var r=document.getElementById('ai-revision');if(!r)return;mount(r);new MutationObserver(function(){mount(r)}).observe(r,{childList:true})});
})();
